style.css:
@-moz-document domain("chess.com") {
/* Ändrar de orangea rutorna till lila */
    .highlight.orange {
        background-color: rgba(155, 89, 182, 0.75) !important;
    }

    /* Ändrar de orangea pilarna till lila */
    polygon[id*="orange"], 
    line[id*="orange"],
    [class*="orange"] {
        stroke: rgb(155, 89, 182) !important;
        fill: rgb(155, 89, 182) !important;
    }
}
